#include <Arduino.h>
#include <DHT.h>

DHT sensor(2, DHT22);
unsigned long lastRead = 0;
bool firstRead = true;

void setup() {
  Serial.begin(9600);
  sensor.begin();
}

void loop() {
  unsigned long now = millis();
  if (firstRead || (unsigned long)(now - lastRead) >= 2000UL) {
    firstRead = false;
    lastRead = now;
    float humidity = sensor.readHumidity();
    if (!isnan(humidity)) {
      Serial.print("Humidity: ");
      Serial.println(humidity, 1);
    }
  }
}
